import {SLOTS,SLOTNAME,RARITY} from './engine.js';
import {casinoInputs,casinoAvailability} from './casino.js';
const esc=t=>String(t??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const freshCasinoBrowser=()=>({kind:'material',search:'',quality:'all',slot:'all',sort:'quality-desc',page:0});
export const CASINO_PAGE_SIZE=24;
export function casinoReason(reason){return ({'invalid-state':'赌场记录无效，请导出备份后检查。',combat:'当前战斗结束后可抽取；手动暂停的战斗请先自行完成。休息期间可直接抽取，不改变自动续战。','pending-operation':'请先领取锻造结果或完成当前重铸。',limit:'已达到本存档的安全抽取上限。',gold:'金币不足，需要100金币。',input:'请选择仍在背包中的合格材料或装备。','amulet-capacity':'项链背包已满；请先留出1格，保证幸运骰子可入包。','equipment-capacity':'请为每个可抽取的装备部位留出1格；投入装备释放的格子也计入。',storage:'保存失败，未扣金币、未消耗投入物；可原样重试。','storage-blocked':'存档已在别处变化，请刷新后继续。',rejected:'条件已经变化，未消耗任何资源，请重新选择。'})[reason]??'暂时无法抽取，未消耗任何资源。';}
export function browseCasinoInputs(s,browser={}){
 const o={...freshCasinoBrowser(),...browser},query=o.search.trim().toLocaleLowerCase('zh-CN'),[field,direction]=o.sort.split('-'),sign=direction==='asc'?1:-1;
 return casinoInputs(s).filter(r=>r.kind===o.kind&&(!query||r.name.toLocaleLowerCase('zh-CN').includes(query))&&(o.quality==='all'||r.quality===Number(o.quality))&&(o.kind!=='equipment'||o.slot==='all'||r.slot===o.slot)).sort((a,b)=>sign*(field==='name'?a.name.localeCompare(b.name,'zh-CN'):field==='level'?(a.level??0)-(b.level??0):a.quality-b.quality)||a.name.localeCompare(b.name,'zh-CN')||a.id.localeCompare(b.id));
}
export function renderCasinoReceipt(r){
 if(!r)return '<p class="subtleText">尚未抽取。请选择材料或装备。</p>';
 const outcome={downgrade:'降一档抽取',upgrade:'升一档抽取',same:'同品质抽取',legendary:'传说大奖'}[r.outcome],quality=['普通','稀有','优良','至臻','传说'];
 return `<section class="casinoReceipt" role="status" aria-live="polite"><small>第 ${r.revision} 次 · 已保存</small><h3>${esc(outcome)}</h3><p>投入：${esc(quality[r.fromQuality]+' '+r.inputName)} ×1 ＋ 100金币</p><p class="r${r.toQuality}text"><strong>获得：${esc(quality[r.toQuality]+' '+r.rewardName)} ×1</strong></p>${r.outcome==='downgrade'&&r.fromQuality===0?'<p>已是普通品质，按普通品质抽取。</p>':''}${r.outcome==='upgrade'&&r.fromQuality===3?'<p>已是至臻品质，按至臻品质抽取。</p>':''}<small>新装备已收入背包，不受战利品过滤影响。</small><button data-casino-result="${esc(r.rewardId)}">查看获得装备</button></section>`;
}
export function renderCasino(s,{browser=freshCasinoBrowser(),selection=null,quote=null,error='',busy=false,queued=false}={}){
 const rows=browseCasinoInputs(s,browser),pages=Math.max(1,Math.ceil(rows.length/CASINO_PAGE_SIZE)),page=Math.min(Math.max(0,browser.page),pages-1),visible=rows.slice(page*CASINO_PAGE_SIZE,(page+1)*CASINO_PAGE_SIZE),chosen=casinoInputs(s).find(r=>r.kind===selection?.kind&&r.id===selection?.id),reason=error||(!chosen?casinoAvailability(s):!quote?.ok?quote?.reason:null);
 const select=(field,label,options)=>`<label>${label}<select data-casino-field="${field}" aria-label="${label}">${options.map(([value,text])=>`<option value="${value}" ${String(browser[field])===value?'selected':''}>${esc(text)}</option>`).join('')}</select></label>`;
 return `<div class="casinoService"><section class="casinoHall" aria-labelledby="casinoHallTitle"><figure class="casinoScene"><img src="./service-assets/casino-hall-v083.webp" width="2172" height="724" alt="烛火照亮石砌赌厅，披风庄家守在绿毡赌桌后，桌上放着骰子与金币。" decoding="async"><figcaption><span>赌场</span><h2 id="casinoHallTitle">命运赌桌</h2><p>骰盅落定，命运揭晓。</p></figcaption></figure><div class="casinoIntro"><p>投入 <strong>1件材料或装备 ＋ 100金币</strong>，抽取一件全新装备。</p><span class="casinoHallMark">固定概率</span></div></section><div class="casinoOdds" aria-label="固定抽取概率"><div><strong>33%</strong><span>降一档抽装备</span><small>普通品质不再降低</small></div><div><strong>33%</strong><span>升一档抽装备</span><small>最高至臻品质</small></div><div><strong>33%</strong><span>同品质抽装备</span><small>全新装备</small></div><div class="casinoJackpot"><strong>1%</strong><span>传说项链 · 幸运骰子</span><small>幸运33 / 攻击33 / 生命333 / 暴击33</small></div></div><div class="casinoLayout"><section class="panel casinoSelection"><h3>选择投入物</h3><div class="casinoTabs"><button data-casino-kind="material" aria-pressed="${browser.kind==='material'}">材料</button><button data-casino-kind="equipment" aria-pressed="${browser.kind==='equipment'}">装备</button></div><div class="casinoFilters"><label>搜索名称<input id="casinoSearch" type="search" value="${esc(browser.search)}" data-casino-field="search" placeholder="搜索投入物" autocomplete="off"></label>${select('quality','品质',[['all','全部品质'],...RARITY.slice(0,4).map((n,i)=>[String(i),n])])}${browser.kind==='equipment'?select('slot','部位',[['all','全部部位'],...SLOTS.filter(k=>k!=='core'||s.race==='ashen').map(k=>[k,SLOTNAME[k]])]):''}${select('sort','排序',[['quality-desc','品质从高到低'],['quality-asc','品质从低到高'],['name-asc','名称排序'],...(browser.kind==='equipment'?[['level-desc','等级从高到低']]:[])])}<button data-casino-reset="1">重置筛选</button></div><div id="casinoPicker" class="casinoPicker">${visible.length?visible.map(r=>`<button class="casinoInput r${r.quality} ${chosen?.id===r.id&&chosen?.kind===r.kind?'isSelected':''}" data-casino-select="${esc(r.id)}" data-casino-input-kind="${r.kind}" aria-pressed="${chosen?.id===r.id&&chosen?.kind===r.kind}"><span class="r${r.quality}text">${esc(r.name)}</span><small>${esc(RARITY[r.quality])} · ${r.kind==='material'?'持有 '+r.count+' 件':esc(SLOTNAME[r.slot])+' · Lv.'+r.level}${r.item?.set?' · 套装':''}</small></button>`).join(''):'<p class="emptyMessage">没有符合筛选的可投入物。</p>'}</div><div class="casinoPagination"><button data-casino-page="${page-1}" ${page===0?'disabled':''}>上一页</button><span>${rows.length} 项 · ${page+1}/${pages}</span><button data-casino-page="${page+1}" ${page+1>=pages?'disabled':''}>下一页</button></div></section><aside class="panel casinoCheckout"><h3>确认抽取</h3><p>${chosen?esc(RARITY[chosen.quality]+' '+chosen.name)+' ×1':'未选择投入物'}</p><p>消耗金币：<strong>100</strong> / 持有 ${s.gold.toLocaleString()}</p><p class="casinoWarning">消耗投入物，获得随机部位与词条的全新装备；不继承原装备属性与成长。</p><button class="primary" data-casino-draw="${quote?.revision??''}" ${busy||!chosen||!quote?.ok?'disabled':''}>${busy?'等待本场结束…':queued?(s.dungeonRun?'本轮副本结束后抽取 · 100金币':'本场结束后抽取 · 100金币'):'投入并抽取 · 100金币'}</button>${reason?`<p class="casinoError" role="status">${esc(casinoReason(reason))}</p>`:''}${renderCasinoReceipt(s.casino?.lastReceipt)}</aside></div><details class="casinoRules"><summary>抽取规则</summary><p>可投入闲置、未锁定的非传说装备；受保护装备与剧情唯一物品除外。材料每次仅消耗1件。</p><p>装备投入：产出同等级装备。材料投入：产出角色等级±2的装备，最低1级。按当前角色种族抽取装备；幸运骰子属性固定。</p><p>每个可产出部位需留1格，包括项链；投入装备腾出的格子可用。保存失败不扣费，获得的装备不受自动丢弃设置影响。</p></details></div>`;
}
